(function(){
  function cartForm(){return document.querySelector('.ps-product-summary form.cart,form.cart')}
  function cartButton(){var form=cartForm();return form&&form.querySelector('.single_add_to_cart_button')}
  function setField(name,value){var form=cartForm();if(!form)return;var input=form.querySelector('input[name="'+name+'"]');if(!input){input=document.createElement('input');input.type='hidden';input.name=name;form.appendChild(input)}input.value=value||''}
  function setLocked(locked){var button=cartButton(),status=document.querySelector('.ps-design-status');if(button){button.disabled=!!locked;button.classList.toggle('ps-design-required',!!locked);button.setAttribute('aria-disabled',String(!!locked))}if(status)status.textContent=locked?'Complete your design before adding this custom product to the cart.':'Your design is ready. You can edit it or add the product to your cart.'}
  function complete(detail){detail=detail||{};var api=window.POD_DESIGNER||{};setField('ps_design_id',detail.designId||(api.getDesignId&&api.getDesignId())||'');setField('ps_design_preview',(detail.previews&&detail.previews[0])||(api.getPrimaryPreview&&api.getPrimaryPreview())||'');setField('ps_design_product_id',(api.getProductId&&api.getProductId())||'');setLocked(false)}
  function reset(){['ps_design_id','ps_design_preview','ps_design_product_id'].forEach(function(name){var form=cartForm(),input=form&&form.querySelector('input[name="'+name+'"]');if(input)input.remove()});setLocked(true)}
  document.addEventListener('hx-pod:design-complete',function(event){complete(event.detail)});
  document.addEventListener('hx-pod:design-reset',reset);
  function init(){if(!document.querySelector('[data-pod-designer]'))return;var api=window.POD_DESIGNER;if(api&&api.isCompleted&&api.isCompleted())complete({});else setLocked(true)}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',function(){setTimeout(init,0)});else setTimeout(init,0);
})();
